// resolveIdentity.js — pure-JS contact identity resolver for n8n Code nodes.
//
// Mirrors src/identity.py resolve_identity EXACTLY, including the core safety rule:
// a row with no valid email can NEVER be net_new. Auto-match only on STRONG keys
// (email / linkedin_url); every weak-key hit routes to ambiguous (needs_review).
//
// PURE: the actual HubSpot searches happen upstream in an n8n HubSpot node. This
// function receives their results pre-fetched as `searchResultsByKey`, a map keyed
// by the search/match name -> array of candidate ids:
//   { email:[ids], linkedin_url:[ids], phone_lastname:[ids], name_company:[ids] }
// A missing key is treated as zero hits.


// Deterministic LinkedIn key — mirrors identity.canonicalize_linkedin.
function canonicalizeLinkedin(url) {
  if (!url) return null;
  let s = String(url).trim();
  if (s === "") return null;
  if (!s.includes("//")) s = "https://" + s;
  let scheme = "", rest = s;
  const schemeIdx = s.indexOf("//");
  if (schemeIdx > 0) {
    scheme = s.slice(0, schemeIdx - 1); // drop the ':' before '//'
    rest = s.slice(schemeIdx + 2);
  } else {
    rest = s.slice(schemeIdx + 2);
  }
  // rest = host[/path][?query][#frag]
  let host = rest, path = "";
  const slash = rest.indexOf("/");
  if (slash >= 0) {
    host = rest.slice(0, slash);
    path = rest.slice(slash);
  }
  // drop query/fragment
  path = path.split("?")[0].split("#")[0];
  if (path.endsWith("/")) path = path.slice(0, -1);
  return scheme.toLowerCase() + "://" + host.toLowerCase() + path;
}

function _ids(searchResultsByKey, key) {
  const v = searchResultsByKey && searchResultsByKey[key];
  return Array.isArray(v) ? v.map(String) : [];
}

function resolveIdentity(row, searchResultsByKey) {
  row = row || {};
  searchResultsByKey = searchResultsByKey || {};

  const email = normalizeEmailBasic(row.email); // null if absent OR malformed
  const linkedin = canonicalizeLinkedin(row.linkedin_url);
  const phone = normalizePhoneAU(row.phone);
  const firstname = String(row.firstname || "").trim();
  const lastname = String(row.lastname || "").trim();
  const company = String(row.company || "").trim();

  // 1. Email (STRONG). A valid email is the ONLY route to net_new.
  if (email) {
    const ids = _ids(searchResultsByKey, "email");
    if (ids.length === 1) {
      return { outcome: "match", contact_id: ids[0], match_key: "email",
               candidate_ids: ids, reason: "single email match" };
    }
    if (ids.length > 1) {
      return { outcome: "ambiguous", contact_id: null, match_key: "email",
               candidate_ids: ids, reason: "multiple email matches" };
    }
    return { outcome: "net_new", contact_id: null, match_key: null,
             candidate_ids: [], reason: "valid email, no existing match" };
  }

  // 2. No valid email past here. LinkedIn (STRONG).
  if (linkedin) {
    const ids = _ids(searchResultsByKey, "linkedin_url");
    if (ids.length === 1) {
      return { outcome: "match", contact_id: ids[0], match_key: "linkedin_url",
               candidate_ids: ids, reason: "single linkedin match" };
    }
    if (ids.length > 1) {
      return { outcome: "ambiguous", contact_id: null, match_key: "linkedin_url",
               candidate_ids: ids, reason: "multiple linkedin matches" };
    }
    // 0 hits -> fall through to weak keys.
  }

  // 3. Weak keys: a hit here is NEVER confident -> only ever ambiguous (review).
  if (phone && lastname) {
    const ids = _ids(searchResultsByKey, "phone_lastname");
    if (ids.length) {
      return { outcome: "ambiguous", contact_id: null, match_key: "phone_lastname",
               candidate_ids: ids, reason: "weak-key match requires review" };
    }
  }

  if (firstname && lastname && company) {
    const ids = _ids(searchResultsByKey, "name_company");
    if (ids.length) {
      return { outcome: "ambiguous", contact_id: null, match_key: "name_company",
               candidate_ids: ids, reason: "weak-key match requires review" };
    }
  }

  // 4. HARD SAFETY RULE: no valid email AND no confident match AND no weak-key
  // candidate -> ambiguous, NEVER net_new.
  return { outcome: "ambiguous", contact_id: null, match_key: null,
           candidate_ids: [], reason: "no email, insufficient identity" };
}

// --- n8n wrapper: strong-key auto-match, weak keys -> review, no-email never net_new ---
return $input.all().map((it) => {
  const row = it.json;
  if (row.reject) {
    return { json: { ...row, identity: { outcome: "rejected", contact_id: null,
      match_key: null, candidate_ids: [], reason: row.reject_reason || "missing identity" } } };
  }
  const identity = resolveIdentity(row, row.searchResultsByKey || {});
  return { json: { ...row, identity } };
});

// mergeContacts.js — pure-JS DETERMINISTIC non-clobber merge for n8n Code nodes.
//
// Mirrors the DETERMINISTIC parts of src/merge_policy.py (deterministic_gate +
// source_metadata + staging_property) for a single upload candidate per field.
// NO Haiku / NO Sonnet — the LLM classification/validation stages that merge_policy
// runs after the gate are intentionally omitted here (n8n Code nodes cannot call
// them; escalation happens in a downstream node). So the decision IS the gate's
// decision. Source = "csv" @ confidence 80 (matches src/ingest.py row_to_provider_result).
//
// Email can NEVER land in canonicalPatch on this enrich path (belt-and-braces: the
// manual_protected class + the 95 threshold already prevent it, and an explicit
// guard enforces it regardless of policy edits).

// Default contacts field policy (source of truth: config/field_policy.yaml `contacts`).
const DEFAULT_CONTACT_POLICY = {
  email:        { class: "manual_protected",  min_confidence: 95 },
  phone:        { class: "fill_blank_only",   min_confidence: 80 },
  mobilephone:  { class: "fill_blank_only",   min_confidence: 85 },
  jobtitle:     { class: "stale_refreshable", min_confidence: 75 },
  linkedin_url: { class: "fill_blank_only",   min_confidence: 85 },
  seniority:    { class: "system_owned",      min_confidence: 75 },
  persona_group:{ class: "system_owned",      min_confidence: 75 },
};

function _isBlank(v) {
  return v === null || v === undefined || v === "" ||
         (Array.isArray(v) && v.length === 0);
}

function stagingProperty(provider, field) {
  return `${provider}_${field}`;
}

function _nowIso() {
  return new Date().toISOString();
}

// Deterministic gate — single candidate, mirrors merge_policy.deterministic_gate.
// has_conflict is always false with one candidate, so the conflict branch is dropped.
function _gate(field, currentValue, confidence, policy) {
  const fieldClass = (policy && policy.class) || "fill_blank_only";
  const minConfidence = (policy && policy.min_confidence != null) ? policy.min_confidence : 80;

  if (confidence < minConfidence) {
    return { decision: "needs_review",
             reason: `Best confidence ${confidence} below threshold ${minConfidence}.` };
  }
  if (fieldClass === "manual_protected") {
    return { decision: "stage_only", reason: "Field is manual_protected." };
  }
  if (fieldClass === "review_required") {
    return { decision: "needs_review", reason: "Field requires review." };
  }
  if (fieldClass === "system_owned" || fieldClass === "score_output" || fieldClass === "veto_output") {
    return { decision: "promote", reason: "System-owned field passed confidence threshold." };
  }
  if (fieldClass === "fill_blank_only") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "stage_only", reason: "Current value exists and field is fill_blank_only." };
  }
  if (fieldClass === "stale_refreshable") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "needs_review", reason: "Refresh candidate requires review in MVP." };
  }
  return { decision: "stage_only", reason: "Default conservative behavior." };
}

function _statusFor(decision) {
  // Deterministic (no LLM) validation_status from source_registry vocabulary.
  return decision === "needs_review" ? "human_review_required" : "provider_only";
}

// mergeContacts(existingProps, candidateRow, fieldPolicy?, opts?)
//   existingProps: current HubSpot contact properties (the record being enriched)
//   candidateRow:  canonical-keyed upload row (post column-map + normalization)
//   fieldPolicy:   contacts policy block; defaults to DEFAULT_CONTACT_POLICY
//   opts:          { source="csv", confidence=80 }
function mergeContacts(existingProps, candidateRow, fieldPolicy, opts) {
  existingProps = existingProps || {};
  candidateRow = candidateRow || {};
  const policy = fieldPolicy || DEFAULT_CONTACT_POLICY;
  const source = (opts && opts.source) || "csv";
  const confidence = (opts && opts.confidence != null) ? opts.confidence : 80;
  const verifiedAt = _nowIso();

  const canonicalPatch = {};
  const stagingPatch = {};
  const metadataPatch = {};
  const decisions = [];

  for (const field of Object.keys(candidateRow)) {
    const value = candidateRow[field];
    if (_isBlank(value)) continue; // nothing to merge

    const currentValue = existingProps[field];
    const fieldPol = policy[field] || { class: "fill_blank_only", min_confidence: 80 };

    // Always stage the raw candidate under its provider-namespaced key.
    stagingPatch[stagingProperty(source, field)] = value;

    const gate = _gate(field, currentValue, confidence, fieldPol);
    let decision = gate.decision;

    // HARD GUARD: email never promotes to canonical on the enrich path.
    if (field === "email" && decision === "promote") decision = "stage_only";

    const validationStatus = _statusFor(decision);

    // Stamp source metadata for every field with a chosen candidate.
    const meta = {
      [`${field}_source`]: source,
      [`${field}_confidence`]: confidence,
      [`${field}_verified_at`]: verifiedAt,
      [`${field}_validation_status`]: validationStatus,
    };
    Object.assign(metadataPatch, meta);

    if (decision === "promote") {
      canonicalPatch[field] = value;
    }

    decisions.push({
      field,
      current_value: currentValue === undefined ? null : currentValue,
      chosen_value: value,
      source_provider: source,
      decision,
      confidence,
      reason: gate.reason,
      validation_status: validationStatus,
      verified_at: verifiedAt,
    });
  }

  return { canonicalPatch, stagingPatch, metadataPatch, decisions };
}

// --- n8n wrapper: deterministic non-clobber merge (email never promotes) ---
return $input.all().map((it) => {
  const row = it.json;
  const candidate = {};
  for (const f of ["email", "firstname", "lastname", "jobtitle", "linkedin_url", "company"]) {
    if (row[f] != null && String(row[f]).trim() !== "") candidate[f] = row[f];
  }
  if (row.phone_normalized) candidate.phone = row.phone_normalized;
  // LOCAL/template: no existing HubSpot props fetched here => {} (blanks promote per policy).
  const merged = mergeContacts({}, candidate, undefined, { source: "csv", confidence: 80 });
  return { json: { ...row, merge: merged } };
});

// Decide Action — CLOUD variant.
// Computes action + the HubSpot property patch, then the IF nodes route to the
// real HubSpot update/create (gated) / Set review nodes.
return $input.all().map((it) => {
  const row = it.json;
  const id = row.identity || {};
  const outcome = id.outcome || "rejected";
  const allow_create = row.allow_create === true;
  const properties = row.merge
    ? { ...row.merge.canonicalPatch, ...row.merge.stagingPatch, ...row.merge.metadataPatch }
    : {};
  let action;
  if (outcome === "match") action = "update";
  else if (outcome === "net_new") action = allow_create ? "create" : "review";
  else if (outcome === "ambiguous") action = "review";
  else action = "skip";
  return { json: {
    action,
    outcome,
    contact_id: id.contact_id || null,
    reason: id.reason || row.reject_reason || null,
    email_status: row.email_status || null,
    properties
  }};
});
